define('APP_ROOT', '..');require __DIR__.'/../includes/auth.php';require_role('admin');require __DIR__.'/../config/database.php';require __DIR__.'/../includes/functions.php';$page_title='Data Anggota';$rows=mysqli_query($koneksi,"SELECT u.*,COUNT(p.id_peminjaman) jumlah,COALESCE(SUM(p.denda),0) denda FROM users u LEFT JOIN peminjaman p ON p.id_user=u.id_user WHERE u.role='user' GROUP BY u.id_user ORDER BY u.created_at DESC");require __DIR__.'/../includes/header.php';?><div class="section-head"><div><p class="eyebrow">MANAJEMEN PENGGUNA</p><h2>Anggota perpustakaan</h2></div><a class="btn primary" href="user_tambah.php"><i class="fa-solid fa-user-plus"></i> Tambah anggota</a></div><section class="panel table-wrap"><table><thead><tr><th>Anggota</th><th>Kontak</th><th>Pinjaman</th><th>Total Denda</th><th></th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($rows)){?><tr><td><b><?=e($r['nama_lengkap'])?></b><small>@<?=e($r['username'])?> · Terdaftar <?=format_tanggal_id($r['created_at'])?></small></td><td><?=e($r['email'])?><small><?=e($r['no_telepon'])?></small></td><td><?=$r['jumlah']?> transaksi</td><td><?=format_rupiah((int)$r['denda'])?></td><td class="actions"><a href="user_detail.php?id=<?=$r['id_user']?>">Detail</a><a href="user_edit.php?id=<?=$r['id_user']?>">Edit</a><a class="danger-link" data-confirm="Menghapus anggota juga menghapus seluruh riwayat peminjamannya. Lanjutkan?" href="user_hapus.php?id=<?=$r['id_user']?>">Hapus</a></td></tr><?php }?></tbody></table></section><?php require __DIR__.'/../includes/footer.php'; ?>
